import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

@Slf4j
class HealthIndicatorsPanel extends PluginPanel
{
	// Index order encodes the marker type: even = percent, odd = HP; 2+ = repeating
	private static final String[] UNITS = {"%", "HP", "Every %", "Every HP"};
	private static final double MAX_PERCENT = 100;
	// 5 digits fits the value field; far above any NPC's max HP
	private static final double MAX_HP = 99_999;
	private static final double MIN_STEP = 1;
	private static final Icon COLLAPSE_ICON = chevron(true);
	private static final Icon EXPAND_ICON = chevron(false);

	private final List<NpcRule> npcRules;
	private final Consumer<List<NpcRule>> onChange;
	private final Set<String> collapsed;
	private final Consumer<Set<String>> onCollapsedChange;
	private final Gson gson;
	@Nullable
	private final ColorPickerManager colorPickerManager;

	HealthIndicatorsPanel(List<NpcRule> npcRules, Consumer<List<NpcRule>> onChange, Set<String> collapsed,
		Consumer<Set<String>> onCollapsedChange, Gson gson, @Nullable ColorPickerManager colorPickerManager)
	{
		this.npcRules = npcRules;
		this.onChange = onChange;
		this.collapsed = collapsed;
		this.onCollapsedChange = onCollapsedChange;
		this.gson = gson;
		this.colorPickerManager = colorPickerManager;
		rebuild();
	}

	private void rebuild()
	{
		removeAll();

		JLabel title = new JLabel("Health Threshold Indicators");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		add(title);

		// Explicit breaks: Swing's HTML wrapping drops a word at the break under a width style
		JLabel help = new JLabel("<html>Add an NPC by name, or a regex.<br>Mark a % or an HP value, or repeat<br>one every % or HP.</html>");
		help.setFont(FontManager.getRunescapeSmallFont());
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(help);

		JPanel topButtons = new JPanel(new GridLayout(1, npcRules.isEmpty() ? 1 : 2, 4, 0));
		topButtons.setOpaque(false);
		JButton addNpc = new JButton("Add NPC");
		addNpc.addActionListener(e ->
		{
			NpcRule rule = new NpcRule();
			npcRules.add(rule);
			collapsed.remove(ImportPlan.key(rule));
			save();
			rebuild();
		});
		topButtons.add(addNpc);

		if (!npcRules.isEmpty())
		{
			boolean anyExpanded = CollapsedRules.anyExpanded(collapsed, npcRules);
			JButton toggleAll = new JButton(anyExpanded ? "Collapse all" : "Expand all");
			toggleAll.addActionListener(e ->
			{
				CollapsedRules.setAll(collapsed, npcRules, anyExpanded);
				saveCollapsed();
				rebuild();
			});
			topButtons.add(toggleAll);
		}
		add(topButtons);

		JPanel importExport = new JPanel(new GridLayout(1, 2, 4, 0));
		importExport.setOpaque(false);
		JButton importButton = new JButton("Import");
		importButton.setToolTipText("Add NPC rules from JSON on the clipboard");
		importButton.addActionListener(e -> importFromClipboard());
		JButton exportButton = new JButton("Export");
		exportButton.setToolTipText("Copy all NPC rules to the clipboard as JSON");
		exportButton.addActionListener(e -> exportToClipboard());
		importExport.add(importButton);
		importExport.add(exportButton);
		add(importExport);

		for (NpcRule rule : npcRules)
		{
			add(createCard(rule));
		}

		revalidate();
		repaint();
	}

	private JPanel createCard(NpcRule rule)
	{
		JPanel card = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(6, 6, 6, 6));

		boolean isCollapsed = CollapsedRules.isCollapsed(collapsed, rule);
		JPanel nameRow = new JPanel(new BorderLayout(4, 0));
		nameRow.setOpaque(false);

		JButton chevron = new JButton(isCollapsed ? EXPAND_ICON : COLLAPSE_ICON);
		chevron.setPreferredSize(new Dimension(18, 18));
		chevron.setToolTipText(isCollapsed ? "Show this NPC's markers" : "Hide this NPC's markers");
		chevron.addActionListener(e ->
		{
			CollapsedRules.toggle(collapsed, rule);
			saveCollapsed();
			rebuild();
		});
		nameRow.add(chevron, BorderLayout.WEST);

		if (isCollapsed)
		{
			JLabel summary = new JLabel(rule.getName().isEmpty() ? "(unnamed)" : rule.getName());
			summary.setForeground(Color.WHITE);
			summary.setToolTipText(describe(rule));
			nameRow.add(summary, BorderLayout.CENTER);

			int count = rule.getMarkers().size();
			JLabel marks = new JLabel(count + (count == 1 ? " mark" : " marks"));
			marks.setFont(FontManager.getRunescapeSmallFont());
			marks.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			marks.setToolTipText(describe(rule));
			nameRow.add(marks, BorderLayout.EAST);

			card.add(nameRow);
			return card;
		}

		JTextField name = new JTextField(rule.getName());
		name.setToolTipText("NPC name, case-insensitive regex (e.g. Alchemical Hydra)");
		updateNameValidity(name);
		name.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				updateNameValidity(name);
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				updateNameValidity(name);
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				updateNameValidity(name);
			}
		});
		Runnable commitName = () ->
		{
			String text = name.getText().trim();
			if (!text.equals(rule.getName()))
			{
				rule.setName(text);
				save();
			}
		};
		name.addActionListener(e -> commitName.run());
		name.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commitName.run();
			}
		});
		nameRow.add(name, BorderLayout.CENTER);
		card.add(nameRow);

		for (NpcRule.Marker marker : rule.getMarkers())
		{
			card.add(createMarkerRow(rule, marker));
		}

		JPanel actions = new JPanel(new GridLayout(1, 2, 4, 0));
		actions.setOpaque(false);
		JButton addMarker = new JButton("Add marker");
		addMarker.addActionListener(e ->
		{
			rule.getMarkers().add(new NpcRule.Marker());
			save();
			rebuild();
		});
		JButton removeNpc = new JButton("Remove");
		removeNpc.setToolTipText("Remove this NPC and its markers");
		removeNpc.addActionListener(e ->
		{
			npcRules.remove(rule);
			save();
			rebuild();
		});
		actions.add(addMarker);
		actions.add(removeNpc);
		card.add(actions);

		return card;
	}

	private JPanel createMarkerRow(NpcRule rule, NpcRule.Marker marker)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);

		// A plain number field rather than a spinner: the sidebar is too narrow for spinner arrows plus the full unit names
		NumberFormatter formatter = new NumberFormatter(new DecimalFormat("0.##"));
		formatter.setValueClass(Double.class);
		applyBounds(formatter, marker.isPercent(), marker.isRepeating());
		JFormattedTextField value = new JFormattedTextField(formatter);
		value.setHorizontalAlignment(JTextField.RIGHT);
		value.setToolTipText("Value; invalid entries revert when you click away");
		value.setValue(clamp(marker.getValue(), marker.isPercent(), marker.isRepeating()));
		value.addPropertyChangeListener("value", e ->
		{
			if (value.getValue() instanceof Number)
			{
				marker.setValue(((Number) value.getValue()).doubleValue());
				save();
			}
		});
		row.add(value, BorderLayout.CENTER);

		int controlHeight = value.getPreferredSize().height;
		JPanel controls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		controls.setOpaque(false);

		JComboBox<String> unit = new JComboBox<>(UNITS);
		unit.setToolTipText("% or HP marks once; Every % / Every HP repeats the mark at that interval");
		unit.setPreferredSize(new Dimension(88, controlHeight));
		unit.setSelectedIndex((marker.isRepeating() ? 2 : 0) + (marker.isPercent() ? 0 : 1));
		unit.addActionListener(e ->
		{
			int index = unit.getSelectedIndex();
			boolean percent = index % 2 == 0;
			boolean repeating = index >= 2;
			double clamped = clamp(marker.getValue(), percent, repeating);
			marker.setPercent(percent);
			marker.setRepeating(repeating);
			marker.setValue(clamped);
			applyBounds(formatter, percent, repeating);
			value.setValue(clamped);
			save();
		});
		controls.add(unit);

		JLabel swatch = new JLabel();
		swatch.setOpaque(true);
		swatch.setToolTipText("Marker color");
		swatch.setBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR));
		swatch.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		swatch.setPreferredSize(new Dimension(16, controlHeight));
		updateSwatch(swatch, marker.getColor());
		swatch.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				openColorPicker(swatch, marker);
			}
		});
		controls.add(swatch);

		JButton remove = new JButton("X");
		remove.setToolTipText("Remove marker");
		remove.addActionListener(e ->
		{
			rule.getMarkers().remove(marker);
			save();
			rebuild();
		});
		remove.setPreferredSize(new Dimension(20, controlHeight));
		controls.add(remove);

		row.add(controls, BorderLayout.EAST);
		return row;
	}

	private void openColorPicker(JLabel swatch, NpcRule.Marker marker)
	{
		if (colorPickerManager == null)
		{
			return;
		}

		RuneliteColorPicker picker = colorPickerManager.create(
			SwingUtilities.windowForComponent(this), new Color(marker.getColor(), true), "Marker color", false);
		picker.setLocation(swatch.getLocationOnScreen());
		picker.setOnColorChange(c ->
		{
			marker.setColor(c.getRGB());
			updateSwatch(swatch, c.getRGB());
		});
		picker.setOnClose(c -> save());
		picker.setVisible(true);
	}

	private void exportToClipboard()
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(gson.toJson(npcRules)), null);
		JOptionPane.showMessageDialog(this, "Copied " + npcRules.size() + " NPC rule(s) to the clipboard.",
			"Export", JOptionPane.INFORMATION_MESSAGE);
	}

	private void importFromClipboard()
	{
		List<NpcRule> imported;
		try
		{
			String json = (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
			log.debug("import: clipboard held {} characters", json == null ? -1 : json.length());
			imported = NpcRule.sanitize(gson.fromJson(json, new TypeToken<ArrayList<NpcRule>>()
			{
			}.getType()));
			log.debug("import: parsed {} rules", imported.size());
		}
		// Reading the Windows clipboard can also throw IllegalStateException when another process holds it
		catch (Exception e)
		{
			log.warn("import: could not read rules from the clipboard", e);
			JOptionPane.showMessageDialog(this, "Couldn't read the clipboard: " + e.getMessage(),
				"Import", JOptionPane.ERROR_MESSAGE);
			return;
		}

		if (imported.isEmpty())
		{
			JOptionPane.showMessageDialog(this, "The clipboard doesn't contain exported NPC rules.",
				"Import", JOptionPane.WARNING_MESSAGE);
			return;
		}

		List<NpcRule> chosen = ImportDialog.show(this, npcRules, imported);
		if (chosen == null || chosen.isEmpty())
		{
			log.debug("import: cancelled");
			return;
		}

		int replaced = ImportPlan.conflicts(npcRules, chosen).size();
		List<NpcRule> merged = ImportPlan.apply(npcRules, chosen);
		npcRules.clear();
		npcRules.addAll(merged);
		// Arrive folded up: a large preset would otherwise bury the panel
		chosen.forEach(rule -> collapsed.add(ImportPlan.key(rule)));
		save();
		saveCollapsed();
		rebuild();
		log.debug("import: {} rules chosen, {} replaced, {} total", chosen.size(), replaced, npcRules.size());
	}

	private void save()
	{
		onChange.accept(npcRules);
	}

	private void saveCollapsed()
	{
		CollapsedRules.prune(collapsed, npcRules);
		onCollapsedChange.accept(collapsed);
	}

	/**
	 * @return this rule's markers as one line, such as "75%, 50%, every 200 HP"
	 */
	private static String describe(NpcRule rule)
	{
		StringBuilder marks = new StringBuilder();
		for (NpcRule.Marker marker : rule.getMarkers())
		{
			if (marks.length() > 0)
			{
				marks.append(", ");
			}
			marks.append(new Threshold(marker.getValue(), marker.isPercent(), marker.isRepeating(), Color.WHITE).describe());
		}
		return marks.length() == 0 ? "No markers yet" : marks.toString();
	}

	private static Icon chevron(boolean pointingDown)
	{
		BufferedImage image = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		Polygon triangle = new Polygon();
		if (pointingDown)
		{
			triangle.addPoint(1, 2);
			triangle.addPoint(7, 2);
			triangle.addPoint(4, 6);
		}
		else
		{
			triangle.addPoint(2, 1);
			triangle.addPoint(6, 4);
			triangle.addPoint(2, 7);
		}
		g.fillPolygon(triangle);
		g.dispose();
		return new ImageIcon(image);
	}

	private static double clamp(double value, boolean percent, boolean repeating)
	{
		return Math.max(repeating ? MIN_STEP : 0, Math.min(value, percent ? MAX_PERCENT : MAX_HP));
	}

	private static void applyBounds(NumberFormatter formatter, boolean percent, boolean repeating)
	{
		formatter.setMinimum(repeating ? MIN_STEP : 0.0);
		formatter.setMaximum(percent ? MAX_PERCENT : MAX_HP);
	}

	private static void updateSwatch(JLabel swatch, int argb)
	{
		// Opaque Swing components can't paint translucent backgrounds cleanly, so show the solid color
		swatch.setBackground(new Color(argb & 0xFFFFFF));
	}

	private static void updateNameValidity(JTextField name)
	{
		boolean valid = RuleCompiler.compilePattern(name.getText()) != null;
		name.setForeground(valid ? Color.WHITE : ColorScheme.PROGRESS_ERROR_COLOR);
	}

	static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setColor(Color.BLACK);
		g.fillRect(0, 5, 16, 6);
		g.setColor(new Color(0, 180, 0));
		g.fillRect(1, 6, 9, 4);
		g.setColor(new Color(180, 0, 0));
		g.fillRect(10, 6, 5, 4);
		g.setColor(Color.WHITE);
		g.fillRect(5, 3, 1, 10);
		g.fillRect(10, 3, 1, 10);
		g.dispose();
		return icon;
	}
}

package com.healththresholds;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Health Threshold Indicators",
	description = "Draws configurable per-NPC HP threshold marks on NPC health bars",
	tags = {"npc", "boss", "health", "hp", "bar", "threshold", "overlay"}
)
public class HealthIndicatorsPlugin extends Plugin
{
	static final String RULES_KEY = "npcRules";
	// Which cards are folded up in the panel. Kept out of the rules so it never rides along in an export.
	static final String COLLAPSED_KEY = "collapsedNpcs";

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HealthIndicatorsOverlay overlay;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ColorPickerManager colorPickerManager;

	@Inject
	private Gson gson;

	private NavigationButton navButton;

	@Getter
	private volatile List<ThresholdRule> rules = Collections.emptyList();

	@Provides
	HealthIndicatorsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HealthIndicatorsConfig.class);
	}

	@Override
	protected void startUp()
	{
		List<NpcRule> npcRules = loadNpcRules();
		rules = RuleCompiler.compile(npcRules);

		HealthIndicatorsPanel panel = new HealthIndicatorsPanel(npcRules, this::saveNpcRules,
			loadCollapsed(), this::saveCollapsed, gson, colorPickerManager);
		navButton = NavigationButton.builder()
			.tooltip("Health Threshold Indicators")
			.icon(HealthIndicatorsPanel.createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		rules = Collections.emptyList();
	}

	private List<NpcRule> loadNpcRules()
	{
		String json = configManager.getConfiguration(HealthIndicatorsConfig.GROUP, RULES_KEY);
		if (Strings.isNullOrEmpty(json))
		{
			return new ArrayList<>();
		}

		try
		{
			return NpcRule.sanitize(gson.fromJson(json, new TypeToken<ArrayList<NpcRule>>()
			{
			}.getType()));
		}
		catch (JsonParseException e)
		{
			log.warn("Unable to parse saved NPC threshold rules", e);
			return new ArrayList<>();
		}
	}

	private Set<String> loadCollapsed()
	{
		String json = configManager.getConfiguration(HealthIndicatorsConfig.GROUP, COLLAPSED_KEY);
		if (Strings.isNullOrEmpty(json))
		{
			return new LinkedHashSet<>();
		}

		try
		{
			Set<String> loaded = gson.fromJson(json, new TypeToken<LinkedHashSet<String>>()
			{
			}.getType());
			return loaded != null ? loaded : new LinkedHashSet<>();
		}
		catch (JsonParseException e)
		{
			log.warn("Unable to parse which NPC cards were collapsed", e);
			return new LinkedHashSet<>();
		}
	}

	private void saveCollapsed(Set<String> collapsed)
	{
		configManager.setConfiguration(HealthIndicatorsConfig.GROUP, COLLAPSED_KEY, gson.toJson(collapsed));
	}

	private void saveNpcRules(List<NpcRule> npcRules)
	{
		rules = RuleCompiler.compile(npcRules);
		configManager.setConfiguration(HealthIndicatorsConfig.GROUP, RULES_KEY, gson.toJson(npcRules));
	}
}

package com.healththresholds;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Window;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * Asks which of the rules on the clipboard to import, flagging the ones that would replace
 * a rule already in the list.
 */
class ImportDialog extends JDialog
{
	private static final Color CONFLICT_TEXT = new Color(228, 165, 60);
	private static final Color CONFLICT_ROW = new Color(58, 48, 30);

	private final Map<JCheckBox, NpcRule> rows = new LinkedHashMap<>();
	private final Set<String> conflicts;
	private final JLabel summary = new JLabel();
	private final JButton importButton = new JButton();

	@Nullable
	private List<NpcRule> selected;

	private ImportDialog(Window owner, List<NpcRule> imported, Set<String> conflicts)
	{
		super(owner, "Import NPC rules", ModalityType.APPLICATION_MODAL);
		this.conflicts = conflicts;

		JPanel root = new JPanel(new BorderLayout(0, 10));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.setBorder(new EmptyBorder(12, 12, 12, 12));
		root.add(createHeader(imported, conflicts), BorderLayout.NORTH);
		root.add(createList(imported), BorderLayout.CENTER);
		root.add(createFooter(), BorderLayout.SOUTH);

		setContentPane(root);
		setMinimumSize(new Dimension(460, 320));
		setPreferredSize(new Dimension(460, Math.min(560, 210 + imported.size() * 32)));
		pack();
		setLocationRelativeTo(owner);
		updateSummary();
	}

	/**
	 * @return the rules to import, or null if cancelled
	 */
	@Nullable
	static List<NpcRule> show(Component parent, List<NpcRule> existing, List<NpcRule> imported)
	{
		Set<String> conflicts = ImportPlan.conflicts(existing, imported);
		// Conflicts first: they're the rows worth reading before importing
		List<NpcRule> ordered = new ArrayList<>(imported);
		ordered.sort(Comparator.comparing(rule -> conflicts.contains(ImportPlan.key(rule)) ? 0 : 1));

		ImportDialog dialog = new ImportDialog(
			javax.swing.SwingUtilities.getWindowAncestor(parent), ordered, conflicts);
		dialog.setVisible(true);
		return dialog.selected;
	}

	private JPanel createHeader(List<NpcRule> imported, Set<String> conflicts)
	{
		JPanel header = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		header.setOpaque(false);

		JLabel title = new JLabel("Import " + imported.size() + " NPC rule" + (imported.size() == 1 ? "" : "s"));
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		header.add(title);

		JLabel subtitle = new JLabel(conflicts.isEmpty()
			? "None of these are in your list yet."
			: conflicts.size() + " are already in your list. Importing those replaces what you have.");
		subtitle.setFont(FontManager.getRunescapeSmallFont());
		subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(subtitle);

		JPanel quick = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 6));
		quick.setOpaque(false);
		quick.add(quickButton("All", rule -> true));
		quick.add(quickButton("None", rule -> false));
		quick.add(quickButton("Only new", rule -> !conflicts.contains(ImportPlan.key(rule))));
		header.add(quick);

		return header;
	}

	private JButton quickButton(String text, java.util.function.Predicate<NpcRule> shouldCheck)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.addActionListener(e ->
		{
			rows.forEach((box, rule) -> box.setSelected(shouldCheck.test(rule)));
			updateSummary();
		});
		return button;
	}

	private JScrollPane createList(List<NpcRule> imported)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setBorder(new EmptyBorder(6, 6, 6, 6));

		for (NpcRule rule : imported)
		{
			list.add(createRow(rule));
			list.add(Box.createVerticalStrut(2));
		}

		JScrollPane scroll = new JScrollPane(list);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR));
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		return scroll;
	}

	private JPanel createRow(NpcRule rule)
	{
		boolean conflict = conflicts.contains(ImportPlan.key(rule));

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(conflict ? CONFLICT_ROW : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(5, 6, 5, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

		JCheckBox box = new JCheckBox(rule.getName(), true);
		box.setOpaque(false);
		box.setForeground(Color.WHITE);
		box.setFont(FontManager.getRunescapeFont());
		box.addActionListener(e -> updateSummary());
		rows.put(box, rule);
		row.add(box, BorderLayout.WEST);

		JLabel detail = new JLabel(conflict ? "replaces yours" : describe(rule));
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(conflict ? CONFLICT_TEXT : ColorScheme.LIGHT_GRAY_COLOR);
		detail.setHorizontalAlignment(SwingConstants.RIGHT);
		detail.setToolTipText(describe(rule));
		row.add(detail, BorderLayout.EAST);

		return row;
	}

	private JPanel createFooter()
	{
		JPanel footer = new JPanel(new BorderLayout(8, 0));
		footer.setOpaque(false);

		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		footer.add(summary, BorderLayout.WEST);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		buttons.setOpaque(false);

		JButton cancel = new JButton("Cancel");
		cancel.setFont(FontManager.getRunescapeSmallFont());
		cancel.addActionListener(e -> dispose());
		buttons.add(cancel);

		importButton.setFont(FontManager.getRunescapeSmallFont());
		importButton.addActionListener(e ->
		{
			selected = checkedRules();
			dispose();
		});
		buttons.add(importButton);
		footer.add(buttons, BorderLayout.EAST);

		// Enter shouldn't replace rules by reflex, so Cancel takes the default
		getRootPane().setDefaultButton(cancel);
		return footer;
	}

	private List<NpcRule> checkedRules()
	{
		List<NpcRule> checked = new ArrayList<>();
		rows.forEach((box, rule) ->
		{
			if (box.isSelected())
			{
				checked.add(rule);
			}
		});
		return checked;
	}

	private void updateSummary()
	{
		int replacing = 0;
		int adding = 0;
		for (NpcRule rule : checkedRules())
		{
			if (conflicts.contains(ImportPlan.key(rule)))
			{
				replacing++;
			}
			else
			{
				adding++;
			}
		}

		int total = adding + replacing;
		int unchecked = rows.size() - total;
		StringBuilder text = new StringBuilder(adding + " new, " + replacing + " replace");
		if (unchecked > 0)
		{
			text.append(", ").append(unchecked).append(" unchecked");
		}
		summary.setText(text.toString());

		importButton.setText("Import " + total);
		importButton.setEnabled(total > 0);
	}

	private static String describe(NpcRule rule)
	{
		StringBuilder marks = new StringBuilder();
		for (NpcRule.Marker marker : rule.getMarkers())
		{
			if (marks.length() > 0)
			{
				marks.append(", ");
			}
			marks.append(new Threshold(marker.getValue(), marker.isPercent(), marker.isRepeating(), Color.WHITE).describe());
		}
		return marks.toString();
	}
}

package com.healththresholds;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Works out which imported rules collide with existing ones, and folds a chosen set into the list.
 * Kept apart from the dialog so the rules can be tested without Swing.
 */
final class ImportPlan
{
	private ImportPlan()
	{
	}

	/**
	 * Rules are matched case-insensitively in game, so names collide the same way.
	 */
	static String key(NpcRule rule)
	{
		return rule.getName() == null ? "" : rule.getName().trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * @return the keys of imported rules that already exist
	 */
	static Set<String> conflicts(List<NpcRule> existing, List<NpcRule> imported)
	{
		Set<String> existingKeys = new HashSet<>();
		for (NpcRule rule : existing)
		{
			existingKeys.add(key(rule));
		}

		Set<String> conflicts = new HashSet<>();
		for (NpcRule rule : imported)
		{
			if (existingKeys.contains(key(rule)))
			{
				conflicts.add(key(rule));
			}
		}
		return conflicts;
	}

	/**
	 * Replaces same-named rules in place, keeping their position in the list, and appends the rest.
	 * Any extra duplicates of a replaced name are dropped, tidying up lists that were appended to
	 * before this existed.
	 *
	 * @return the merged list
	 */
	static List<NpcRule> apply(List<NpcRule> existing, List<NpcRule> selected)
	{
		List<NpcRule> result = new ArrayList<>(existing);

		for (NpcRule rule : selected)
		{
			String key = key(rule);
			int first = -1;
			for (int i = result.size() - 1; i >= 0; i--)
			{
				if (key(result.get(i)).equals(key))
				{
					if (first >= 0)
					{
						result.remove(first);
					}
					first = i;
				}
			}

			if (first >= 0)
			{
				result.set(first, rule);
			}
			else
			{
				result.add(rule);
			}
		}
		return result;
	}
}

package com.healththresholds;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Saved form of one NPC's markers, stored as JSON in the plugin's config.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
class NpcRule
{
	private String name = "";
	private List<Marker> markers = new ArrayList<>();

	/**
	 * Replaces nulls from hand-edited or imported JSON so the rules are safe to edit.
	 */
	static List<NpcRule> sanitize(List<NpcRule> rules)
	{
		List<NpcRule> result = new ArrayList<>();
		if (rules == null)
		{
			return result;
		}
		for (NpcRule rule : rules)
		{
			if (rule == null)
			{
				continue;
			}
			List<Marker> markers = new ArrayList<>();
			if (rule.getMarkers() != null)
			{
				rule.getMarkers().stream().filter(Objects::nonNull).forEach(markers::add);
			}
			result.add(new NpcRule(rule.getName() == null ? "" : rule.getName(), markers));
		}
		return result;
	}

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	static class Marker
	{
		private double value = 50;
		private boolean percent = true;
		private boolean repeating;
		private int color = 0xFFFFFFFF;
	}
}

package com.healththresholds;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Turns saved NPC rules into render-ready rules, dropping blank names, invalid
 * regexes and out-of-range markers.
 */
final class RuleCompiler
{
	private RuleCompiler()
	{
	}

	static List<ThresholdRule> compile(List<NpcRule> npcRules)
	{
		if (npcRules == null || npcRules.isEmpty())
		{
			return Collections.emptyList();
		}

		List<ThresholdRule> rules = new ArrayList<>();
		for (NpcRule npcRule : npcRules)
		{
			Pattern pattern = compilePattern(npcRule.getName());
			if (pattern == null || npcRule.getMarkers() == null)
			{
				continue;
			}

			List<Threshold> thresholds = new ArrayList<>();
			for (NpcRule.Marker marker : npcRule.getMarkers())
			{
				if (marker == null || marker.getValue() < 0 || (marker.isPercent() && marker.getValue() > 100)
					|| (marker.isRepeating() && marker.getValue() <= 0))
				{
					continue;
				}
				thresholds.add(new Threshold(marker.getValue(), marker.isPercent(), marker.isRepeating(), new Color(marker.getColor(), true)));
			}

			if (!thresholds.isEmpty())
			{
				rules.add(new ThresholdRule(pattern, thresholds));
			}
		}
		return rules;
	}

	/**
	 * @return the case-insensitive pattern for an NPC name, or null if blank or invalid
	 */
	static Pattern compilePattern(String name)
	{
		if (name == null || name.isBlank())
		{
			return null;
		}
		try
		{
			return Pattern.compile(name.trim(), Pattern.CASE_INSENSITIVE);
		}
		catch (PatternSyntaxException e)
		{
			return null;
		}
	}
}

package com.healththresholds;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Value;

@Value
class Threshold
{
	// Bounds work per frame for tiny steps on huge HP pools; the bar is at most a few hundred pixels wide anyway
	private static final int MAX_REPEATS = 10_000;

	double value;
	boolean percent;
	/**
	 * When set, marks repeat every {@code value} (percent or HP) across the bar instead of appearing once.
	 */
	boolean repeating;
	Color color;

	/**
	 * @return this mark as it reads in the UI, such as "50%" or "every 200 HP"
	 */
	String describe()
	{
		String number = java.math.BigDecimal.valueOf(value).stripTrailingZeros().toPlainString();
		String unit = percent ? number + "%" : number + " HP";
		return repeating ? "every " + unit : unit;
	}

	/**
	 * @return positions along the bar from 0 to 1; empty for HP thresholds when the NPC's max HP is unknown
	 */
	List<Double> ratios(@Nullable Integer maxHealth)
	{
		double total;
		if (percent)
		{
			total = 100;
		}
		else if (maxHealth != null && maxHealth > 0)
		{
			total = maxHealth;
		}
		else
		{
			return Collections.emptyList();
		}

		if (!repeating)
		{
			return value <= total ? List.of(value / total) : Collections.emptyList();
		}

		if (value <= 0)
		{
			return Collections.emptyList();
		}

		List<Double> ratios = new ArrayList<>();
		for (int k = 1; k <= MAX_REPEATS && k * value < total - 1e-9; k++)
		{
			ratios.add(k * value / total);
		}
		return ratios;
	}
}

