import java.awt.Rectangle;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class BarTrackerTest
{
	private static final Rectangle ESTIMATE = new Rectangle(1013, 175, 120, 5);

	@Test
	public void detectionIsUsedAsIs()
	{
		BarTracker tracker = new BarTracker();
		Rectangle detected = new Rectangle(1012, 173, 120, 5);

		assertEquals(detected, tracker.resolve(1, ESTIMATE, detected, 0));
	}

	@Test
	public void aMissReusesTheLastOffset()
	{
		// Hydra's bar sat 1px left and 2px above the estimate; a miss should keep it there
		BarTracker tracker = new BarTracker();
		tracker.resolve(1, ESTIMATE, new Rectangle(1012, 173, 120, 5), 0);

		Rectangle moved = new Rectangle(1030, 140, 120, 5);
		assertEquals(new Rectangle(1029, 138, 120, 5), tracker.resolve(1, moved, null, 1_000));
	}

	@Test
	public void aMissWithNoHistoryHasNothingToOffer()
	{
		assertNull(new BarTracker().resolve(1, ESTIMATE, null, 0));
	}

	@Test
	public void staleOffsetsExpire()
	{
		BarTracker tracker = new BarTracker();
		tracker.resolve(1, ESTIMATE, new Rectangle(1012, 173, 120, 5), 0);

		assertNull(tracker.resolve(1, ESTIMATE, null, BarTracker.HOLD_MS + 1));
	}

	@Test
	public void eachNpcKeepsItsOwnOffset()
	{
		BarTracker tracker = new BarTracker();
		tracker.resolve(1, ESTIMATE, new Rectangle(1012, 173, 120, 5), 0);
		tracker.resolve(2, ESTIMATE, new Rectangle(1015, 176, 120, 5), 0);

		assertEquals(new Rectangle(1012, 173, 120, 5), tracker.resolve(1, ESTIMATE, null, 100));
		assertEquals(new Rectangle(1015, 176, 120, 5), tracker.resolve(2, ESTIMATE, null, 100));
	}

	@Test
	public void longGoneNpcsAreForgotten()
	{
		BarTracker tracker = new BarTracker();
		tracker.resolve(1, ESTIMATE, new Rectangle(1012, 173, 120, 5), 0);
		tracker.resolve(2, ESTIMATE, new Rectangle(1012, 173, 120, 5), 60_000);

		assertEquals(1, tracker.size());
	}
}

package com.healththresholds;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CollapsedRulesTest
{
	private static NpcRule rule(String name)
	{
		return new NpcRule(name, new ArrayList<>());
	}

	@Test
	public void togglingFoldsAndUnfolds()
	{
		Set<String> collapsed = new LinkedHashSet<>();
		NpcRule hydra = rule("Alchemical Hydra");

		assertTrue(CollapsedRules.toggle(collapsed, hydra));
		assertTrue(CollapsedRules.isCollapsed(collapsed, hydra));

		assertFalse(CollapsedRules.toggle(collapsed, hydra));
		assertFalse(CollapsedRules.isCollapsed(collapsed, hydra));
		assertTrue(collapsed.isEmpty());
	}

	@Test
	public void stateIgnoresCaseAndSurroundingSpace()
	{
		Set<String> collapsed = new LinkedHashSet<>();
		CollapsedRules.toggle(collapsed, rule("Alchemical Hydra"));

		assertTrue(CollapsedRules.isCollapsed(collapsed, rule(" alchemical hydra ")));
	}

	@Test
	public void setAllCollapsesOrExpandsEverything()
	{
		List<NpcRule> rules = List.of(rule("Nex"), rule("Cerberus"));
		Set<String> collapsed = new LinkedHashSet<>();

		CollapsedRules.setAll(collapsed, rules, true);
		assertEquals(2, collapsed.size());
		assertFalse(CollapsedRules.anyExpanded(collapsed, rules));

		CollapsedRules.setAll(collapsed, rules, false);
		assertTrue(collapsed.isEmpty());
		assertTrue(CollapsedRules.anyExpanded(collapsed, rules));
	}

	@Test
	public void oneExpandedCardCountsAsExpanded()
	{
		List<NpcRule> rules = List.of(rule("Nex"), rule("Cerberus"));
		Set<String> collapsed = new LinkedHashSet<>();
		CollapsedRules.toggle(collapsed, rules.get(0));

		assertTrue(CollapsedRules.anyExpanded(collapsed, rules));
	}

	@Test
	public void pruningDropsRulesThatNoLongerExist()
	{
		Set<String> collapsed = new LinkedHashSet<>(List.of("nex", "cerberus", "deleted boss"));

		CollapsedRules.prune(collapsed, List.of(rule("Nex"), rule("Cerberus")));

		assertEquals(Set.of("nex", "cerberus"), collapsed);
	}
}

package com.healththresholds;

import java.awt.Rectangle;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class FindBarTest
{
	private static final int W = 200;
	private static final int H = 100;
	private static final int GREEN = 0x00FF00;
	private static final int RED = 0xFF0000;
	private static final int GROUND = 0x303030;

	private static int[] frame()
	{
		int[] pixels = new int[W * H];
		java.util.Arrays.fill(pixels, GROUND);
		return pixels;
	}

	private static void drawBar(int[] pixels, int x, int y, int width, int greenWidth)
	{
		for (int row = y; row < y + 5; row++)
		{
			for (int col = x; col < x + width; col++)
			{
				pixels[row * W + col] = col < x + greenWidth ? GREEN : RED;
			}
		}
	}

	@Test
	public void findsBarOffsetFromEstimate()
	{
		int[] pixels = frame();
		drawBar(pixels, 96, 47, 30, 20);

		assertEquals(new Rectangle(96, 47, 30, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(100, 44, 30, 5)));
	}

	@Test
	public void prefersBarNearestEstimate()
	{
		int[] pixels = frame();
		drawBar(pixels, 100, 41, 30, 30);
		drawBar(pixels, 100, 51, 30, 5);

		assertEquals(new Rectangle(100, 51, 30, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(100, 49, 30, 5)));
	}

	@Test
	public void noBarReturnsNull()
	{
		assertNull(HealthIndicatorsOverlay.findBar(frame(), W, H, new Rectangle(100, 48, 30, 5)));
	}

	@Test
	public void ignoresShortColoredRuns()
	{
		int[] pixels = frame();
		drawBar(pixels, 100, 48, 12, 12);

		assertNull(HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(100, 48, 30, 5)));
	}

	@Test
	public void measuresWiderBossBar()
	{
		int[] pixels = frame();
		drawBar(pixels, 40, 60, 120, 90);

		assertEquals(new Rectangle(40, 60, 120, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(42, 58, 120, 5)));
	}

	@Test
	public void clampsSearchAtFrameEdges()
	{
		int[] pixels = frame();
		drawBar(pixels, 0, 0, 30, 30);

		assertEquals(new Rectangle(0, 0, 30, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(-3, -2, 30, 5)));
	}

	@Test
	public void rejectsBarWidenedBySceneryTouchingIt()
	{
		// The Hydra bug: red flames right beside a 120px bar were read as bar, giving 165-182px widths
		int[] pixels = frame();
		drawBar(pixels, 40, 60, 120, 90);
		fill(pixels, 160, 60, 40, 5, RED);

		assertNull(HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(40, 60, 120, 5)));
	}

	@Test
	public void sceneryWithAGapDoesNotWidenTheBar()
	{
		int[] pixels = frame();
		drawBar(pixels, 40, 60, 120, 90);
		fill(pixels, 164, 60, 30, 5, GREEN);

		assertEquals(new Rectangle(40, 60, 120, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(40, 60, 120, 5)));
	}

	@Test
	public void bridgesAMarkDrawnAcrossTheBar()
	{
		int[] pixels = frame();
		drawBar(pixels, 100, 48, 30, 20);
		fill(pixels, 115, 48, 1, 5, 0xFFFFFF);

		assertEquals(new Rectangle(100, 48, 30, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(100, 48, 30, 5)));
	}

	private static void fill(int[] pixels, int x, int y, int width, int height, int rgb)
	{
		for (int row = y; row < y + height; row++)
		{
			for (int col = x; col < x + width; col++)
			{
				pixels[row * W + col] = rgb;
			}
		}
	}

	@Test
	public void findsABarThatHasMovedWellAboveTheEstimate()
	{
		// Hydra's bar rode 8px+ above the estimate while it walked; the old window clipped it
		int[] pixels = frame();
		drawBar(pixels, 40, 40, 120, 90);

		assertEquals(new Rectangle(40, 40, 120, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(41, 52, 120, 5)));
	}

	@Test
	public void trimsSceneryTouchingTheRightEnd()
	{
		// Seen in the second Hydra fight: 121-124px runs with the left edge in place
		int[] pixels = frame();
		drawBar(pixels, 40, 60, 120, 90);
		fill(pixels, 160, 60, 3, 5, RED);

		assertEquals(new Rectangle(40, 60, 120, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(40, 60, 120, 5)));
	}

	@Test
	public void trimsSceneryTouchingTheLeftEnd()
	{
		int[] pixels = frame();
		drawBar(pixels, 40, 60, 120, 90);
		fill(pixels, 37, 60, 3, 5, GREEN);

		assertEquals(new Rectangle(40, 60, 120, 5), HealthIndicatorsOverlay.findBar(pixels, W, H, new Rectangle(40, 60, 120, 5)));
	}
}

